// Generates the shared parts of the lite-wearable (Watch Fit) build from the ArkTS app,
// so both versions have a single source of truth:
//
//  1. entry/src/main/ets/core/*.ets  ->  lite/.../MainAbility/core/*.js   (ES5, ES modules)
//  2. entry/src/main/resources/{base,en,es}/element/string.json
//                                    ->  lite/.../MainAbility/i18n/strings.js
//     Only keys used by the lite sources are included (lite JS heap is small).
//
// Usage:
//   node tools/build-lite.mjs           regenerate
//   node tools/build-lite.mjs --check   fail (exit 1) if generated files are out of date
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const require = createRequire(import.meta.url);
const check = process.argv.includes('--check');

const tsCandidates = [
  process.env.TS_PATH,
  'C:/Program Files/Huawei/DevEco Studio/sdk/default/openharmony/ets/build-tools/ets-loader/node_modules/typescript',
  '/Applications/DevEco-Studio.app/Contents/sdk/default/openharmony/ets/build-tools/ets-loader/node_modules/typescript',
  'typescript'
].filter(Boolean);
let ts;
for (const c of tsCandidates) {
  try { ts = require(c); break; } catch { /* try next */ }
}
if (!ts) { console.error('TypeScript not found: set TS_PATH'); process.exit(2); }

const coreSrc = path.join(root, 'entry/src/main/ets/core');
const liteJs = path.join(root, 'lite/entry/src/main/js/MainAbility');
const HEADER = '// GENERATED by tools/build-lite.mjs from entry/src/main/ets/core — do not edit.\n';
const outputs = new Map();

// 1. Core
for (const f of fs.readdirSync(coreSrc).filter((n) => n.endsWith('.ets')).sort()) {
  const src = fs.readFileSync(path.join(coreSrc, f), 'utf8');
  let js = ts.transpileModule(src, {
    compilerOptions: {
      module: ts.ModuleKind.ES2015, target: ts.ScriptTarget.ES5, removeComments: false,
      newLine: ts.NewLineKind.LineFeed
    }
  }).outputText;
  js = js.replace(/from '\.\/(\w+)'/g, "from './$1.js'");
  outputs.set(path.join(liteJs, 'core', f.replace(/\.ets$/, '.js')), HEADER + js);
}

// 2. Strings: collect keys referenced by lite sources as s.key / t('key') / fmt('key'
const used = new Set();
const candidates = new Set();
const walk = (dir) => {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) {
      if (e.name !== 'core' && e.name !== 'i18n') walk(p);
    } else if (/\.(hml|js)$/.test(e.name)) {
      const src = fs.readFileSync(p, 'utf8');
      // s.key in templates, and any quoted identifier in scripts that names a string resource
      if (e.name.endsWith('.hml')) {
        for (const m of src.matchAll(/\bs\.([A-Za-z0-9_]+)/g)) used.add(m[1]);
      }
      for (const m of src.matchAll(/'([a-z][A-Za-z0-9_]*)'/g)) candidates.add(m[1]);
    }
  }
};
walk(liteJs);
const LANGS = { ru: 'base', en: 'en', es: 'es' };
const baseKeys = new Set(JSON.parse(fs.readFileSync(path.join(root, 'entry/src/main/resources/base/element/string.json'),
  'utf8')).string.map((e) => e.name));
for (const c of candidates) if (baseKeys.has(c)) used.add(c);
const dict = {};
const missing = [];
for (const [lang, dir] of Object.entries(LANGS)) {
  const file = path.join(root, 'entry/src/main/resources', dir, 'element/string.json');
  const table = new Map(JSON.parse(fs.readFileSync(file, 'utf8')).string.map((e) => [e.name, e.value]));
  dict[lang] = {};
  for (const k of [...used].sort()) {
    if (table.has(k)) dict[lang][k] = table.get(k);
    else if (lang === 'ru') missing.push(k);
  }
}
if (missing.length) {
  console.error(`Lite sources reference unknown string keys: ${missing.join(', ')}`);
  process.exit(1);
}
outputs.set(path.join(liteJs, 'i18n/strings.js'),
  '// GENERATED by tools/build-lite.mjs from entry/src/main/resources/*/element/string.json — do not edit.\n' +
  `// ${used.size} keys used by the lite UI. ru is the default and the fallback.\n` +
  `export default ${JSON.stringify(dict, null, 1)};\n`);

let stale = 0;
for (const [file, content] of outputs) {
  const old = fs.existsSync(file) ? fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n') : null;
  if (old === content) continue;
  stale++;
  if (check) {
    console.log(`out of date: ${path.relative(root, file)}`);
  } else {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, content);
    console.log(`wrote ${path.relative(root, file)}`);
  }
}
if (check && stale) {
  console.log('\nRun: node tools/build-lite.mjs');
  process.exitCode = 1;
} else {
  console.log(`${outputs.size} generated files, ${stale} ${check ? 'stale' : 'updated'}; ${used.size} string keys`);
}
